package processor

import (
	"errors"

	"github.com/devicechain-io/dc-microservice/credential"
	"github.com/nats-io/nats.go"
)

// ProvisioningPolicies are the two kinds device self-registration compares, both Unthrottled.
//
//   - KindProvisioningProfile: a profile's shared secret. It is generated by the server from 256
//     random bits, so a per-key backoff buys no guessing resistance and would hand a stranger
//     who knows a provision key a way to lock every device out of its own profile. The cost of
//     a flood is bounded where the requests arrive (a read deadline, a slot bound, per-source
//     and per-tenant buckets), not here.
//   - KindProvisionedCredential: the REPLAY compare, a device presenting again the material it
//     registered with. A kind of its own so that a mismatch charges nothing to the MQTT connect
//     backoff of the username the device presents to the broker (KindDeviceCredential).
//
// credential.NewChecker refuses either kind with any other policy.
var ProvisioningPolicies = map[credential.Kind]credential.Policy{
	credential.KindProvisioningProfile:   {Unthrottled: true},
	credential.KindProvisionedCredential: {Unthrottled: true},
}

// NewProvisioningChecker builds the Checker device self-registration compares through. main.go
// calls this and nothing else, and the model's AuthenticateProvisioningProfile and
// ProvisionDevice read their secrets through it.
//
// 🔴 THE KEYS ARE PARAMETERS, NOT OPTIONS, and they are the SAME values the Api digests with
// (Api.DeviceSecretKey and Api.EnrollmentKeys.Provisioning). A digest written under one key
// verifies only under that key: a Checker handed the claim key or the device key where the
// provisioning key belongs would refuse every profile in the instance, and one handed the
// provisioning key for the replay kind would refuse every replay. The wiring test over this
// function writes a digest through the Api and verifies it through the Checker main.go builds.
//
// The kinds are Unthrottled and never read or write an attempt record, so the store it is
// given is one that FAILS every call: if a later change made a kind throttled the Checker
// would refuse construction (ErrMustBeUnthrottled), and if anything reached the store anyway
// the attempt would error rather than silently count in a bucket it was not meant for.
func NewProvisioningChecker(deviceKey *credential.DeviceSecretKey, enrollment *credential.EnrollmentSecretKeys,
	opts ...credential.Option) (*credential.Checker, error) {
	if enrollment == nil {
		return nil, errors.New("a provisioning checker needs the enrollment secret keys")
	}
	return credential.NewChecker(unusedAttemptStore{}, ProvisioningPolicies, append([]credential.Option{
		credential.WithDeviceSecretKey(deviceKey),
		credential.WithProvisioningSecretKey(enrollment.Provisioning),
	}, opts...)...)
}

// unusedAttemptStore is the attempt store of a Checker whose every kind is Unthrottled.
type unusedAttemptStore struct{}

var errUnusedAttemptStore = errors.New("provisioning checks keep no attempt record")

func (unusedAttemptStore) Get(string) (nats.KeyValueEntry, error) { return nil, errUnusedAttemptStore }
func (unusedAttemptStore) Create(string, []byte) (uint64, error)  { return 0, errUnusedAttemptStore }
func (unusedAttemptStore) Update(string, []byte, uint64) (uint64, error) {
	return 0, errUnusedAttemptStore
}
func (unusedAttemptStore) Delete(string, ...nats.DeleteOpt) error { return errUnusedAttemptStore }
